class Solution {
public:
    vector<int> prevPermOpt1(vector<int>& arr) {
        int n = arr.size();
        int i = n - 2;
        while (i >= 0 && arr[i] <= arr[i + 1]) {
            i--;
        }
        if (i < 0) return arr;

        int max_val = -1, best_j = -1;
        for (int j = i + 1; j < n; ++j) {
            if (arr[j] < arr[i]) {
                if (arr[j] > max_val) {
                    max_val = arr[j];
                    best_j = j;
                }
            }
        }

        swap(arr[i], arr[best_j]);
        return arr;
    }
};

class Solution {
    public int[] prevPermOpt1(int[] arr) {
        int n = arr.length;
        int i = n - 2;
        while (i >= 0 && arr[i] <= arr[i + 1]) {
            i--;
        }
        if (i < 0) return arr;

        int maxVal = -1, bestJ = -1;
        for (int j = i + 1; j < n; ++j) {
            if (arr[j] < arr[i]) {
                if (arr[j] > maxVal) {
                    maxVal = arr[j];
                    bestJ = j;
                }
            }
        }

        int temp = arr[i];
        arr[i] = arr[bestJ];
        arr[bestJ] = temp;
        return arr;
    }
}

